from contextlib import contextmanager
import fcntl

@contextmanager
def exclusive_lock(path):
    with open(path, "w") as handle:
        fcntl.flock(handle, fcntl.LOCK_EX)
        try:
            yield handle
        finally:
            fcntl.flock(handle, fcntl.LOCK_UN)

def run(path):
    with exclusive_lock("/tmp/migrate.lock"):
        apply_pending(path)
